/* ================================================================
   5. 登录账号与权限
   ----------------------------------------------------------------
   三个演示账号，密码统一 123456：
   · 个人端（求职者）  王旭
   · 企业端            深圳市云启科技有限公司
   生成单角色 html 时，只替换下面 BUILD 这一行（fixedRole / accounts）。
   ================================================================ */
const BUILD = (function(){
  const r = document.body ? document.body.getAttribute('data-role') : '';
  const role = (r === 'personal') ? 'person' : (r === 'enterprise' ? 'company' : null);
  /* 单端入口只接受本端账号；共享页不限制 */
  return { fixedRole: role, accounts: role ? [role] : ['company','person'] };
})();

const ACCOUNTS = {
  person:{
    key:'person', label:'个人端', acc:'王旭', pwd:'123456',
    segTxt:'个人端登录', subTxt:'求职者 · 投递 / 学习 / 成长',
    name:'王旭', roleTxt:'求职中 · AI 产品经理', avatar:'王'
  },
  company:{
    key:'company', label:'企业端', acc:'深圳市云启科技有限公司', pwd:'123456',
    segTxt:'企业端登录', subTxt:'招聘 / 发布 / 管理',
    name:'云启科技', roleTxt:'企业管理员', avatar:'云'
  },
};
const LOGIN_ROLES = BUILD.accounts.slice();

/* 记住密码：本地存账号与密码（base64），下次打开自动填好，但仍需点「登录」 */
const REMEMBER_KEY = 'daka_remember_account_v1';
function readRemember(){
  try{ return JSON.parse(localStorage.getItem(REMEMBER_KEY) || 'null'); }catch(e){ return null; }
}
function writeRemember(st){
  try{ st ? localStorage.setItem(REMEMBER_KEY, JSON.stringify(st)) : localStorage.removeItem(REMEMBER_KEY); }
  catch(e){}
}
function encodePwd(p){ try{ return btoa(unescape(encodeURIComponent(p))); }catch(e){ return p; } }
function decodePwd(p){ try{ return decodeURIComponent(escape(atob(p))); }catch(e){ return p; } }

const state = {
  role:'all',                // all=功能整合版（暂不分端）| company | person（定稿后由登录分配）
  page:'job',
  view:'card',               // 卡片 | 列表
  tab:{},                    // key -> 当前状态 tab（'all' 或状态码）
  kw:{},                     // key -> 关键词
  fv:{},                     // key -> {filterKey:value}
  applied:{},                // key -> Set（求职端已投递/报名）
  sel:new Set(),             // 企业端表格勾选
  editId:null,
  quotaUsed:QUOTA.used
};

/* ---------- 登录页交互 ---------- */
let loginRole = BUILD.fixedRole || LOGIN_ROLES[0];

/* 渲染身份入口：多角色 → 分段标签；单角色 → 固定身份条 */
function renderLoginUI(){
  const seg = $('roleSeg');   /* 登录页已不再展示身份切换，seg 为 null 时跳过即可 */
  if(BUILD.fixedRole){
    if(seg){
      const a = ACCOUNTS[loginRole];
      const box = document.createElement('div');
      box.className = 'login-role';
      box.innerHTML = '<span class="lr-tag">' + esc(a.label) + '</span>'
        + '<span class="lr-sub">' + esc(a.subTxt) + '</span>';
      seg.parentNode.replaceChild(box, seg);
    }
  }else if(seg){
    seg.classList.toggle('tri', LOGIN_ROLES.length >= 2);   /* 两端起改为上下两行，避免标签被挤换行 */
    seg.innerHTML = LOGIN_ROLES.map(r=>
      '<button type="button" data-role="' + r + '" class="' + (r===loginRole?'active':'') + '">'
      + esc(ACCOUNTS[r].segTxt)
      + '<span class="seg-sub">' + esc(ACCOUNTS[r].subTxt) + '</span></button>').join('');
    seg.querySelectorAll('button').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        loginRole = btn.dataset.role;
        seg.querySelectorAll('button').forEach(b=>b.classList.toggle('active', b.dataset.role===loginRole));
        fillLoginForm();
        clearLErr('f-acc'); clearLErr('f-pwd'); $('agree-msg').classList.remove('show');
        $('acc').focus();
      });
    });
  }

  /* 演示账号提示 */
  $('demoAcc').innerHTML = LOGIN_ROLES.map(r=>{
    const a = ACCOUNTS[r];
    return '<div>' + esc(a.label) + '　<code>' + esc(a.acc) + '</code>　密码 <code>' + esc(a.pwd) + '</code></div>';
  }).join('') + '<div>登录账号决定可见模块与可执行操作（权限分配）。</div>';

  if(BUILD.fixedRole){
    if($('authSub')) $('authSub').textContent = '本页为「' + ACCOUNTS[loginRole].label + '」专属入口，使用下方账号登录';
  }
}

/* 首次：带出账号、密码留空；记住过：账号密码一起填好（仍需点登录）
   onlyAccount=true → 只带账号、密码留空（退出登录后使用） */
function fillLoginForm(onlyAccount){
  const rm = readRemember();
  const hit = rm && rm.role === loginRole && LOGIN_ROLES.indexOf(rm.role) > -1;
  if(hit && !onlyAccount){
    $('acc').value = rm.account || ACCOUNTS[loginRole].acc;
    $('pwd').value = decodePwd(rm.pwd || '');
    if($('rmName')) $('rmName').textContent = $('acc').value;
    if($('rmRole')) $('rmRole').textContent = ACCOUNTS[loginRole].label;
    if($('remembered')) $('remembered').classList.add('show');
  }else{
    $('acc').value = ACCOUNTS[loginRole].acc;
    $('pwd').value = '';
    if($('remembered')) $('remembered').classList.remove('show');
  }
}

function setLErr(fid, msg){
  const f = $(fid);
  f.classList.add('invalid');
  const m = f.querySelector('.l-msg');
  m.textContent = msg;
  m.classList.add('show');
}
function clearLErr(fid){
  const f = $(fid);
  f.classList.remove('invalid');
  const m = f.querySelector('.l-msg');
  m.textContent = '';
  m.classList.remove('show');
}

const EYE_ON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M2.2 12S5.8 5.6 12 5.6 21.8 12 21.8 12 18.2 18.4 12 18.4 2.2 12 2.2 12Z"/><circle cx="12" cy="12" r="2.9"/></svg>';
const EYE_OFF = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3l18 18"/><path d="M10.6 6.1A9.9 9.9 0 0 1 12 6c6.2 0 9.8 6 9.8 6a17 17 0 0 1-3.2 3.9"/><path d="M6.5 7.7A16.8 16.8 0 0 0 2.2 12s3.6 6 9.8 6a9.6 9.6 0 0 0 4.1-.9"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';
if($('pwdEye')) $('pwdEye').addEventListener('click', ()=>{
  const show = $('pwd').type === 'password';
  $('pwd').type = show ? 'text' : 'password';
  $('pwdEye').innerHTML = show ? EYE_OFF : EYE_ON;
  $('pwdEye').classList.toggle('on', show);
  $('pwdEye').title = show ? '隐藏密码' : '显示密码';
});

if($('acc') && $('pwd')) ['acc','pwd'].forEach(id=>{
  $(id).addEventListener('input', ()=>{
    clearLErr(id === 'acc' ? 'f-acc' : 'f-pwd');
  });
  $(id).addEventListener('keydown', e=>{ if(e.key === 'Enter' && $('btnLogin')) $('btnLogin').click(); });
});

/* ================================================================
   登录页：账号即身份。首次输入密码，之后自动记住账号与密码，
   但仍需手动点「登录」才进入（不做自动登录）
   ================================================================ */
const ENABLE_LOGIN = true;

/* ================================================================
   准入会话（sessionStorage · 标签页级）
   ----------------------------------------------------------------
   多页结构下登录态要跨页面保持，所以会话存在 sessionStorage：
   · 新开标签页 / 新窗口打开任何页面 → 无会话 → 先到登录页
   · 登录后在同一标签页内切换菜单 → 沿用会话，不重复登录
   · 关闭标签页 → 会话清除
   会话记录角色，个人端页面不接受企业端会话，反之亦然。
   ================================================================ */
const SESSION_KEY = 'daka_session_v1';
const AUTH = { on:false, role:null, at:0 };

function readSession(){
  try{ return JSON.parse(sessionStorage.getItem(SESSION_KEY) || 'null'); }catch(e){ return null; }
}
function writeSession(role){
  const st = { role:role, at:Date.now() };
  try{ sessionStorage.setItem(SESSION_KEY, JSON.stringify(st)); }catch(e){}
  AUTH.on = true; AUTH.role = role; AUTH.at = st.at;
  return st;
}
function clearSession(){
  try{ sessionStorage.removeItem(SESSION_KEY); }catch(e){}
  AUTH.on = false; AUTH.role = null; AUTH.at = 0;
}
function isAuthed(){
  if(AUTH.on === true) return true;
  const st = readSession();
  if(st && st.role){ AUTH.on = true; AUTH.role = st.role; AUTH.at = st.at; return true; }
  return false;
}
function roleHome(role){
  const first = (PERM[role] && PERM[role][0]) || 'project';
  return PAGE_ROUTES[first] || 'shared/project-outsourcing.html';
}

/* 登录页提交：账号 + 密码 + 协议校验，通过后建立会话并跳转 */
if($('btnLogin')) $('btnLogin').addEventListener('click', ()=>{
  const a = $('acc').value.trim();
  const p = $('pwd').value.trim();
  clearLErr('f-acc'); clearLErr('f-pwd'); $('agree-msg').classList.remove('show');

  if(!a){ setLErr('f-acc','请输入账号'); $('acc').focus(); return; }
  const roleKey = LOGIN_ROLES.filter(r=>ACCOUNTS[r].acc === a)[0];
  if(!roleKey){
    setLErr('f-acc', '账号不存在，演示账号：' + LOGIN_ROLES.map(r=>ACCOUNTS[r].acc).join(' / '));
    $('acc').focus(); return;
  }
  if(roleKey !== loginRole) loginRole = roleKey;
  if(!p){ setLErr('f-pwd','请输入密码'); $('pwd').focus(); return; }
  if(p !== ACCOUNTS[roleKey].pwd){ setLErr('f-pwd','密码不正确，演示密码为 ' + ACCOUNTS[roleKey].pwd); $('pwd').focus(); return; }
  if($('agree') && !$('agree').checked){
    const m = $('agree-msg');
    m.textContent = '请阅读并同意《用户服务协议》与《隐私政策》';
    m.classList.add('show');
    return;
  }

  writeRemember({role:roleKey, account:a, pwd:encodePwd(p), at:Date.now()});
  doEnter(roleKey);
});

/* 登录成功 → 建立会话 → 进入该角色的第一个工作台页面 */
function doEnter(role){
  if(!ACCOUNTS[role]) return;
  writeSession(role);
  location.href = ROOT + roleHome(role);
}

/* ---------- 顶栏身份展示 ---------- */
/* ================================================================
   后台权限配置：角色 → 可见模块（真实项目里由后台下发）
   ----------------------------------------------------------------
   person  求职者：找机会与成长
   company 企业  ：招人、发包与采购
   sp      服务商：提供服务、承接与收益
   ================================================================ */
const ROLES = {
  person:{ key:'person', label:'求职者', short:'个人端',
    chip:'求职者 · 找机会与成长',
    who:{ name:'王旭', role:'求职中 · AI 产品经理', avatar:'王', crumb:'求职者' } },
  company:{ key:'company', label:'企业', short:'企业端',
    chip:'企业 · 招人、发包与采购',
    who:{ name:'云启科技', role:'企业管理员 · 已认证', avatar:'云', crumb:'企业' } },
  sp:{ key:'sp', label:'服务商', short:'服务商端',
    chip:'服务商 · 已下线',
    who:{ name:'服务商端', role:'已下线', avatar:'服', crumb:'服务商' } }
};

const PERM = {
  person:[
    'job','project','outs','consult','train','coach','career','intern',
    /* 求职者也可以作为甲方发布项目外包 / 咨询需求 → 开放对应发布端界面 */
    'projectManage','consultManage',
    /* 个人端不展示「工单与交易 → 订单中心」 */
    'resume','applyP','myCourse','interview','complaint','setting'
  ],
  company:[
    /* 企业端核心业务：项目外包 / 岗位外包 / 数智化咨询 / AI培训
       （不展示 岗位招聘、AI私教、AI职业规划、AI实习） */
    'project','outs','consult','train',
    'certEnt',
    /* 发布端：岗位发布 / 项目外包 / 数智化咨询 / AI培训 / AI私教（原服务商端发布能力并入） */
    'publishManage','projectManage','consultManage','trainManage','coachManage',
    'applyE',
    'complaint','setting'
  ],
  /* 服务商端已下线：原服务商的发布能力（AI培训 / AI私教）并入企业端发布端管理 */
  sp:[ 'setting' ]
};

/* ---------- 顶栏身份展示 ---------- */
function applyRoleUI(){
  const r = ROLES[state.acting] || ROLES.person;
  $('crumbRole').textContent = r.who.crumb;
  $('roleChipTxt').textContent = r.chip;
  $('pfAvatar').innerHTML = avHTML(state.acting === 'company' ? 6 : 7, state.acting === 'company' ? 'm' : 'm');
  $('pfName').textContent = r.who.name;
  $('pfRole').textContent = r.who.role;
}
/* 详情页（无独立菜单，从列表进入）不受菜单权限限制 */
const DETAIL_PAGES = ['candidate','bidDetail','teacher'];
function canSee(key){
  if(DETAIL_PAGES.indexOf(key) > -1) return true;
  const list = PERM[state.acting] || PERM.person;
  const mg = MANAGE_MODULES.find(x=>x.key===key);
  const base = mg ? mg.key : key;
  return list.indexOf(base) > -1;
}
function firstPageOf(role){
  const list = PERM[role] || [];
  return list[0] || 'job';
}

/* ---------- 个人下拉 / 退出 ---------- */
if($('btnProfile')) $('btnProfile').addEventListener('click', e=>{
  e.stopPropagation();
  $('pfMenu').classList.toggle('show');
});
document.addEventListener('click', ()=>{
  if($('pfMenu')) $('pfMenu').classList.remove('show');
});
if($('pmInfo')) $('pmInfo').addEventListener('click', ()=>{
  $('pfMenu').classList.remove('show');
  const r = ROLES[state.acting];
  toast('当前身份：'+r.label+' · '+r.who.name);
});
if($('pmLogout')) $('pmLogout').addEventListener('click', logout);
if($('btnLogout')) $('btnLogout').addEventListener('click', logout);
/* 退出：回到登录页；密码清空，必须重新输入密码才能再进入 */
function logout(){
  const r = AUTH.role || state.acting || 'company';
  clearSession();
  location.href = ROOT + (ROLE_DIR[r] || 'enterprise') + '/index.html';
}

/* ================================================================
   6. 侧边栏构建（核心业务 + 功能管理，按角色过滤）
   ================================================================ */
function buildSidebar(){
  const core = CORE.filter(m=>canSee(m.key));
  const coreHtml = core.length
    ? '<div class="nav-group-title">核心业务</div>' + core.map(m=>
        `<a class="nav-item" href="${navHref(m.key)}" data-page="${m.key}" title="${esc(m.title)}"><span class="ico">${m.icon}</span><span class="label">${m.title}</span></a>`
      ).join('')
    : '';

  /* 按 group 字段分组渲染，分组顺序按首次出现顺序固定；可见性由 PERM 决定 */
  const visible = EXTRA_NAV.filter(n=>canSee(n.key));
  const groups = [];
  const byGroup = {};
  visible.forEach(n=>{
    const g = n.group || '功能管理';
    if(!byGroup[g]){ byGroup[g] = []; groups.push(g); }
    byGroup[g].push(n);
  });
  let extraHtml = '';
  groups.forEach(g=>{
    extraHtml += `<div class="nav-group-title">${g}</div>` + byGroup[g].map(n=>
      `<a class="nav-item" href="${navHref(n.key)}" data-page="${n.key}" title="${esc(n.title)}"><span class="ico">${n.icon||ICONS.apply}</span><span class="label">${n.title}</span>`
      + (n.badge ? `<span class="nav-badge">${n.badge}</span>` : '')
      + `</a>`
    ).join('');
  });

  $('sideNav').innerHTML = coreHtml + extraHtml;
}

/* ---------- 侧边栏收起 / 展开 ---------- */
const SIDE_KEY = 'daka_side_collapsed';
function readSideCollapsed(){
  try{ return localStorage.getItem(SIDE_KEY) === '1'; }
  catch(e){ return false; }
}
function applySideCollapsed(collapsed){
  if($('appPage')) $('appPage').classList.toggle('collapsed', collapsed);
  if($('btnSideToggle')) $('btnSideToggle').title = collapsed ? '展开侧边栏' : '收起侧边栏';
  try{ localStorage.setItem(SIDE_KEY, collapsed ? '1' : '0'); }catch(e){}
}
if($('btnSideToggle')) $('btnSideToggle').addEventListener('click', ()=>{
  applySideCollapsed(!$('appPage').classList.contains('collapsed'));
});

/* ================================================================
   7. 路由
   ----------------------------------------------------------------
   菜单项 → 跳转到对应的独立页面（每个菜单一个 html）
   详情页（候选人 / 项目申请人 / 讲师主页）→ 在当前页内切换视图
   ================================================================ */
const ROOT = '../';
/* 角色 key 与目录名的对应关系（company → enterprise，person → personal） */
const ROLE_DIR = { company:'enterprise', person:'personal' };
const PAGE_ROUTES = {
  /* ---- 个人端 ---- */
  job:'personal/job-recruitment.html',
  coach:'personal/ai-coach.html',
  career:'personal/ai-career-plan.html',
  intern:'personal/ai-internship.html',
  resume:'personal/resume.html',
  applyP:'personal/my-applications.html',
  myCourse:'personal/my-courses.html',
  interview:'personal/interview-management.html',
  /* ---- 企业端 ---- */
  certEnt:'enterprise/enterprise-certification.html',
  publishManage:'enterprise/position-publishing.html',
  trainManage:'enterprise/ai-training-management.html',
  coachManage:'enterprise/ai-coach-management.html',
  applyE:'enterprise/received-applications.html',
  /* ---- 双端共用 ---- */
  project:'shared/project-outsourcing.html',
  outs:'shared/position-outsourcing.html',
  consult:'shared/digital-consulting.html',
  train:'shared/ai-training.html',
  projectManage:'shared/project-outsourcing-management.html',
  consultManage:'shared/digital-consulting-management.html',
  complaint:'shared/complaint-feedback.html',
  setting:'shared/account-settings.html'
};

function navHref(key){
  const p = PAGE_ROUTES[key];
  return p ? (ROOT + p) : 'javascript:void(0)';
}

function go(key){
  if(!isAuthed()){ location.replace(ROOT + 'enterprise/index.html'); return; }
  if(DETAIL_PAGES.indexOf(key) > -1){
    state.page = key;
    state.sel.clear();
    const pt = (typeof PAGE_TITLES !== 'undefined') ? PAGE_TITLES[key] : null;
    if($('crumbNow')) $('crumbNow').textContent = pt || key;
    const box = $('pageBox');
    if(!box) return;
    if(key === 'candidate') renderCandidate(box);
    else if(key === 'bidDetail') renderBidDetail(box);
    else if(key === 'teacher') renderTeacher(box);
    window.scrollTo(0,0);
    return;
  }
  /* 目标就是当前页（如讲师主页点「返回列表」）：页内重绘，避免整页刷新 */
  const cur = document.body.getAttribute('data-page');
  if(key === cur){ setCrumb(key); renderCurrentPage(key); window.scrollTo(0,0); return; }
  navigate(key);
}

function navigate(key){
  const p = PAGE_ROUTES[key];
  if(!p){ toast('该模块暂未开放'); return; }
  location.href = ROOT + p;
}

/* ================================================================
   8. 页面启动：校验会话 → 还原侧边栏 / 顶栏 → 渲染当前页
   ----------------------------------------------------------------
   每个页面在 <body> 上声明 data-role（enterprise / personal / shared）
   与 data-page（本页菜单 key），由这里统一装配。
   ================================================================ */
/* 面包屑：菜单 key → 模块标题 */
function setCrumb(key){
  const m = CORE.find(x=>x.key===key);
  const mg = MANAGE_MODULES.find(x=>x.key===key);
  const ex = EXTRA_NAV.find(x=>x.key===key);
  const pt = (typeof PAGE_TITLES !== 'undefined') ? PAGE_TITLES[key] : null;
  if($('crumbNow')) $('crumbNow').textContent = m ? m.title : (mg ? mg.title : (ex ? ex.title : (pt || key)));
}

function renderCurrentPage(key){
  const box = $('pageBox');
  if(!box) return;
  if(key === 'career' && typeof renderAiPlanPage === 'function'){ renderAiPlanPage(); return; }
  const m = CORE.find(x=>x.key===key);
  if(m){ renderCorePage(m); return; }
  const mg = MANAGE_MODULES.find(x=>x.key===key);
  if(mg){ const v = manageView(mg); if(v) renderCorePage(v); return; }
  if(typeof renderExtraPage === 'function') renderExtraPage(key);
}

function bootPage(){
  const body = document.body;
  const need = body.getAttribute('data-role') || 'shared';
  const key = body.getAttribute('data-page') || '';
  const st = readSession();

  if(!st || !st.role){
    location.replace(ROOT + ((need === 'personal') ? 'personal' : 'enterprise') + '/index.html');
    return false;
  }
  if(need !== 'shared' && ROLE_DIR[st.role] !== need){
    /* 已登录但走错了端：回到自己端的首页，不打断会话、不踢回登录页 */
    location.replace(ROOT + roleHome(st.role));
    return false;
  }

  state.acting = st.role;
  state.role = st.role;
  AUTH.on = true; AUTH.role = st.role; AUTH.at = st.at;
  document.documentElement.setAttribute('data-auth','ok');

  applyRoleUI();
  buildSidebar();
  applySideCollapsed(readSideCollapsed());

  setCrumb(key);

  document.querySelectorAll('#sideNav .nav-item').forEach(el=>
    el.classList.toggle('active', el.dataset.page === key));

  renderCurrentPage(key);
  return true;
}
